  "implementation": "def solve(case):
    payload = case.get('payload', {})
    nodes = payload.get('nodes', [])
    required_symbols = set(payload.get('required_symbols', []))
    if not nodes:
        raise ValueError('No nodes')
    id_to_node = {}
    for n in nodes:
        nid = n.get('id')
        if nid is None:
            raise ValueError('Node missing id')
        id_to_node[nid] = n
    # build children mapping
    children = {nid: [] for nid in id_to_node}
    parent_exists = set()
    root_id = None
    for n in nodes:
        nid = n['id']
        par = n.get('parent')
        if par is None:
            if root_id is not None:
                raise ValueError('Multiple roots')
            root_id = nid
        else:
            if par not in id_to_node:
                raise ValueError(f'Parent {par} not found')
            children[par].append(nid)
            parent_exists.add(nid)
    if root_id is None:
        raise ValueError('No root')
    # check that required symbols exist at start
    all_symbols = {n['symbol'] for n in nodes}
    for sym in required_symbols:
        if sym not in all_symbols:
            raise ValueError(f'Required symbol {sym} missing')
    retained = set(id_to_node.keys())
    removal_order = []
    # order: deeper depth first, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    # precompute subtree sets? We'll compute on the fly using recursion from current retained set
    def get_subtree_ids(node_id):
        # returns set of retained descendant ids including node_id
        result = set()
        stack = [node_id]
        while stack:
            cur = stack.pop()
            if cur not in retained:
                continue
            result.add(cur)
            for child in children.get(cur, []):
                if child in retained:
                    stack.append(child)
        return result

    for n in sorted_nodes:
        nid = n['id']
        if nid not in retained:
            continue
        if nid == root_id:
            continue
        if n['symbol'] in required_symbols:
            continue
        if not n.get('removable', False):
            continue
        # check if any child is retained
        has_retained_child = any(cid in retained for cid in children[nid])
        if has_retained_child:
            continue
        # gather all retained descendants
        subtree = get_subtree_ids(nid)
        # determine required symbols in subtree
        sub_req_syms = set()
        for sid in subtree:
            sym = id_to_node[sid]['symbol']
            if sym in required_symbols:
                sub_req_syms.add(sym)
        if sub_req_syms:
            # check if each required symbol appears outside subtree
            outside_counts = {}
            for sym in sub_req_syms:
                outside_counts[sym] = 0
            for sid in retained:
                if sid in subtree:
                    continue
                sym = id_to_node[sid]['symbol']
                if sym in sub_req_syms:
                    outside_counts[sym] += 1
            if all(outside_counts[sym] >= 1 for sym in sub_req_syms):
                # ok to remove
                retained.remove(nid)
                removal_order.append(nid)
        else:
            # no required symbols in subtree, safe to remove
            retained.remove(nid)
            removal_order.append(nid)
    # final check: ensure required symbols still present
    final_symbols = set()
    for nid in retained:
        final_symbols.add(id_to_node[nid]['symbol'])
    if not required_symbols.issubset(final_symbols):
        # this should not happen due to checks, but just in case
        raise ValueError('Reduction removed required symbol')
    return {
        'retained': sorted(retained),
        'removal_order': removal_order
    }
